parser.script:
var WW_BASE = (typeof context !== "undefined" && context.baseUrl)
  ? String(context.baseUrl).replace(/\/+$/, "")
  : "https://www.duanju55.com";
var WW_DETAIL_RE = /\/vod\/detail\/id\/(\d+)\.html/;

function wwArg(a) {
  if (typeof a === "string") return a;
  if (a && typeof a === "object" && a.length && typeof a[0] === "string") return a[0];
  return "";
}
function wwCtx(k) {
  return (typeof context !== "undefined" && context[k] != null) ? String(context[k]) : "";
}
function wwDec(s) {
  try { return decodeURIComponent(String(s)); } catch (e) { return String(s); }
}
function wwText(s) {
  return String(s == null ? "" : s)
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/gi, " ").replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"').replace(/&#39;/g, "'")
    .replace(/\s+/g, " ").trim();
}
function wwAttr(tag, name) {
  var m = new RegExp(name + "\\s*=\\s*[\"']([^\"']+)[\"']", "i").exec(tag || "");
  return m ? m[1] : "";
}
function wwAbs(u) {
  u = String(u || "").trim();
  if (!u) return "";
  if (/^https?:\/\//i.test(u)) return u;
  if (u.indexOf("//") === 0) return "https:" + u;
  if (u.charAt(0) === "/") return WW_BASE + u;
  return "";
}
function wwCover(block) {
  var re = /<img\b[^>]*>/gi, m;
  while ((m = re.exec(block))) {
    var u = wwAttr(m[0], "data-src") || wwAttr(m[0], "data-original") || wwAttr(m[0], "src");
    if (!u || u.indexOf("data:") === 0) continue;
    if (/logo|avatar|icon|blank|placeholder|loading|qrcode/i.test(u)) continue;
    return wwAbs(u);
  }
  return "";
}
// 通用卡片扫描：不依赖站点 CSS module 类名，靠详情页链接定位每张卡
function wwCards(html) {
  var out = [], seen = {};
  if (!html) return out;
  var re = /<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>/gi, m;
  while ((m = re.exec(html))) {
    var idm = WW_DETAIL_RE.exec(m[1] || "");
    if (!idm) continue;
    var id = idm[1];
    if (seen[id]) continue;
    seen[id] = 1;
    var start = m.index - 900; if (start < 0) start = 0;
    var end = m.index + 900; if (end > html.length) end = html.length;
    var block = html.substring(start, end);
    var after = html.substring(m.index, end);
    var close = after.indexOf("</a>");
    var inner = close >= 0 ? after.substring(0, close + 4) : after.substring(0, 200);
    var title = wwText(inner);
    if (!title) title = wwAttr(m[0], "title");
    if (!title) {
      var alt = /<img\b[^>]*alt\s*=\s*["']([^"']+)["']/i.exec(block);
      if (alt) title = wwText(alt[1]);
    }
    if (!title) continue;
    out.push({
      id: id,
      title: title,
      cover: wwCover(block),
      detailUrl: WW_BASE + "/index.php/vod/detail/id/" + id + ".html"
    });
  }
  return out;
}
// ---------- 分集：覆盖 content__playlist / playlink / pcDrama_catalog* / catalogItem / playlist ----------
function wwEpisodeTitle(t) {
  return !!t && !/^(播放|立即播放|在线播放|下载|收藏|分享|详情)$/.test(t);
}
function parseEpisodes(raw) {
  var html = wwArg(raw);
  if (!html) return [];
  var out = [], seen = {};
  var re = /<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, m;
  while ((m = re.exec(html))) {
    var href = m[1] || "";
    if (!/\/play\/|^play\/|vodplay|drama-play|episode_id=/i.test(href)) continue;
    var title = wwText(m[2]);
    if (!wwEpisodeTitle(title)) continue;
    if (/^javascript:/i.test(href)) continue;
    var url = wwAbs(href);
    if (!url && href) url = WW_BASE + "/" + href.replace(/^\.?\//, "");
    if (!url || seen[url]) continue;
    seen[url] = 1;
    out.push({ id: url, title: title, url: url });
  }
  return out;
}

function wwDead(html) {
  return /Welcome to nginx|nginx\.org/i.test(String(html || "")) && String(html || "").length < 2000;
}
function wwBlocked(html) {
  if (!html) return true;
  // 站点已停用/域名被回收：nginx 默认页（此时任何兜底地址都没意义，直接终止）
  if (wwDead(html)) return false;
  if (/没有找到|暂无相关|无相关|没有数据|没有内容|暂无内容/.test(html)) return false;
  if (html.length < 600) return true;
  if (/系统错误|访问验证|安全验证|请升级会员|会员专享|Just a moment|captcha/i.test(html)) return true;
  return false;
}

// ---------- 搜索：先按原地址解析，失败再依次换 3 种常见搜索地址 ----------
function wwSearchForms() {
  var e = encodeURIComponent(wwCtx("keyword"));
  var page = wwCtx("page") || "1";
  return [
    "/index.php/vod/search/wd/" + e + ".html",
    "/index.php/vod/search.html?wd=" + e,
    "/index.php/vod/search/page/" + page + "/wd/" + e
  ];
}
function wwSearchFallback(i) {
  var forms = wwSearchForms();
  if (!wwCtx("keyword") || i >= forms.length) return [];
  return {
    __meta: true,
    __fetchUrl: forms[i],
    __fetchResponseType: "text",
    __processor: "searchHop" + (i + 1)
  };
}
function wwSearchCheck(raw, i) {
  var html = wwArg(raw);
  var items = wwCards(html);
  if (items.length) return items;
  if (!wwBlocked(html)) return [];
  return wwSearchFallback(i);
}
function parseSearch(raw) {
  var items = wwCards(wwArg(raw));
  if (items.length) return items;
  if (!wwBlocked(wwArg(raw))) return [];
  return wwSearchFallback(0);
}
function searchHop1(raw) { return wwSearchCheck(raw, 1); }
function searchHop2(raw) { return wwSearchCheck(raw, 2); }
function searchHop3(raw) { return wwSearchCheck(raw, 3); }

// ---------- 分类：从首页导航发现，不写死任何类型 id ----------
function parseCategories(raw) {
  var html = wwArg(raw);
  var out = [], seen = {};
  var re = /<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, m;
  while ((m = re.exec(html))) {
    var t = /\/vod\/type\/(?:id\/)?(\d+)/.exec(m[1] || "");
    if (!t) continue;
    var id = t[1];
    var title = wwText(m[2]);
    if (!title || title.length > 8) continue;
    if (/首页|全部|更多|排行|登录|注册|下载|APP|我的/i.test(title)) continue;
    if (seen[id]) continue;
    seen[id] = 1;
    out.push({ id: id, title: title });
    if (out.length >= 24) break;
  }
  return out;
}
function parseCategory(raw) {
  var html = wwArg(raw);
  var items = wwCards(html);
  if (items.length) return items;
  if (wwDead(html)) return [];
  var cat = wwCtx("category");
  var page = wwCtx("page") || "1";
  if (cat === "all" || !cat) {
    return { __meta: true, __fetchUrl: "/", __fetchResponseType: "text", __processor: "categoryHome" };
  }
  if (page !== "1") {
    return {
      __meta: true,
      __fetchUrl: "/index.php/vod/type/id/" + cat + "/page/" + page + ".html",
      __fetchResponseType: "text",
      __processor: "categoryPage"
    };
  }
  return [];
}
function categoryHome(raw) { return wwCards(wwArg(raw)); }
function categoryPage(raw) { return wwCards(wwArg(raw)); }

// ---------- 播放：先取播放器配置，再全页收集候选并按清晰度排序 ----------
function wwPlayerCfg(html) {
  var i = html.indexOf("player_aaaa");
  if (i < 0) return null;
  var k = html.indexOf("{", i);
  if (k < 0) return null;
  var d = 0, e = -1, j;
  for (j = k; j < html.length; j++) {
    var c = html.charAt(j);
    if (c === "{") d++;
    else if (c === "}") { d--; if (d === 0) { e = j + 1; break; } }
  }
  if (e < 0) return null;
  var txt = html.substring(k, e);
  try { return JSON.parse(txt); } catch (err) {}
  var u = /"url"\s*:\s*"([^"]*)"/.exec(txt);
  var en = /"encrypt"\s*:\s*"?(\d+)"?/.exec(txt);
  if (!u) return null;
  return { url: u[1], encrypt: en ? parseInt(en[1], 10) : 0 };
}
function wwDecodePlay(u, enc) {
  var s = String(u || "");
  if (!s) return "";
  enc = parseInt(enc || 0, 10);
  if (enc === 2) { try { s = atob(s); } catch (e) {} s = wwDec(s); }
  else if (enc === 1) { s = wwDec(s); }
  if (!/^https?:\/\//i.test(s) && !/^\/\//.test(s)) {
    if (s.charAt(0) === "/") s = WW_BASE + s;
    else if (s) s = WW_BASE + "/" + s;
  }
  return s;
}
function wwUnescape(u) {
  var s = String(u || "").replace(/\\\//g, "/");
  s = s.replace(/^[,\\。，;；\s]+/, "").replace(/[,\\。，;；\s]+$/, "");
  return s;
}
// 短剧 CDN 常见：路径倒数第二段是 \uXXXX 转义的中文目录（p.* / c1.* 节点），
// 直接拼进播放器会 404；还原成中文目录后指向 index.m3u8（对齐参考实现的归一化）。
function wwFixUnicodeFolder(u) {
  if (!/p\.|c1\./i.test(u)) return "";
  var parts = String(u).split("/");
  if (parts.length < 3) return "";
  var folder = parts[parts.length - 2];
  if (!/\\?u[0-9a-fA-F]{4}/.test(folder)) return "";
  var decoded = folder.replace(/\\?u([0-9a-fA-F]{4})/g, function (_, h) {
    return String.fromCharCode(parseInt(h, 16));
  });
  if (decoded === folder) return "";
  var base = parts.slice(0, parts.length - 2).join("/");
  return base + "/" + encodeURIComponent(decoded) + "/index.m3u8";
}
function wwScore(u) {
  var l = String(u || "").toLowerCase(), s = 0;
  if (/2160|4k/.test(l)) s += 400;
  if (/1080|fhd|blu/.test(l)) s += 300;
  if (/720|hd/.test(l)) s += 200;
  if (/540/.test(l)) s += 120;
  if (/480/.test(l)) s += 60;
  if (/360|sd/.test(l)) s += 20;
  if (/master\.m3u8/.test(l)) s += 80;
  if (/\.m3u8/.test(l)) s += 30;
  if (/preview|trailer|sample|试看|广告|ad\./.test(l)) s -= 500;
  return s;
}
function wwLabel(u, i) {
  var l = String(u || "").toLowerCase();
  if (/2160|4k/.test(l)) return "4K";
  if (/1080/.test(l)) return "1080P";
  if (/720/.test(l)) return "720P";
  if (/540/.test(l)) return "540P";
  if (/480/.test(l)) return "480P";
  if (/360/.test(l)) return "360P";
  return "线路" + (i + 1);
}
function wwAdd(list, seen, u, bonus, anyOk) {
  u = wwAbs(wwUnescape(u));
  if (!u) return;
  var fixed = wwFixUnicodeFolder(u);
  if (fixed) {
    if (!seen[fixed]) {
      seen[fixed] = 1;
      list.push({ url: fixed, score: wwScore(fixed) + (bonus || 0) + 200 });
    }
  }
  if (!anyOk && !/\.(m3u8|mp4)(\?|$)/i.test(u)) return;
  if (seen[u]) return;
  seen[u] = 1;
  list.push({ url: u, score: wwScore(u) + (bonus || 0) });
}
function parseVideo(raw) {
  var html = wwArg(raw);
  if (!html) return "";
  var cands = [], seen = {}, i, m;
  var cfg = wwPlayerCfg(html);
  if (cfg && cfg.url) wwAdd(cands, seen, wwDecodePlay(cfg.url, cfg.encrypt), 50, true);
  var tagRe = /<(?:video|source)\b[^>]*>/gi;
  while ((m = tagRe.exec(html))) {
    wwAdd(cands, seen, wwAttr(m[0], "data-src") || wwAttr(m[0], "src"), 40, true);
  }
  var flat = html.replace(/\\\//g, "/");
  var urlRe = /https?:\/\/[^"'\\\s,)\]]+?\.(?:m3u8|mp4)(?:\?[^"'\\\s,)\]]*)?/gi;
  while ((m = urlRe.exec(flat))) wwAdd(cands, seen, m[0], 0);
  if (!cands.length) return "";
  cands.sort(function (a, b) { return b.score - a.score; });
  var lines = [], max = cands.length < 5 ? cands.length : 5;
  for (i = 0; i < max; i++) {
    lines.push({ name: wwLabel(cands[i].url, i), url: cands[i].url });
  }
  var best = cands[0].url;
  return {
    url: best,
    type: /m3u8/i.test(best) ? "m3u8" : "mp4",
    lines: lines
  };
}
